    out = [row[:] for row in grid]

    def bands(n, occupied):
        result = []
        i = 0
        while i < n:
            if not occupied(i):
                i += 1
                continue
            start = i
            while i < n and occupied(i):
                i += 1
            result.append((start, i - 1))
        return result

    rb = bands(h, lambda r: any(v != 0 for v in grid[r]))
    cb = bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
    # A genuine tile contains its frame and at least one interior row/column;
    # isolated clipped frame strips at the outer edge are not tile centers.
    rb = [b for b in rb if b[1] - b[0] + 1 >= 3]
    cb = [b for b in cb if b[1] - b[0] + 1 >= 3]
    if not rb or not cb:
        return out

    def nominal(groups):
        sizes = [b - a + 1 for a, b in groups]
        return max(set(sizes), key=sizes.count)

    th, tw = nominal(rb), nominal(cb)
    ih, iw = max(1, th - 2), max(1, tw - 2)
    tiles = []
    colors = []
    for r0, r1 in rb:
        row = []
        for c0, c1 in cb:
            patch = [
                [grid[r][c] for c in range(c0 + 1, min(c0 + 1 + iw, w, c1 + 1))]
                for r in range(r0 + 1, min(r0 + 1 + ih, h, r1 + 1))
            ]
            vals = [v for line in patch for v in line if v != 0]
            color = max(set(vals), key=vals.count) if vals else None
            row.append(color)
            if color is not None:
                colors.append(color)
        tiles.append(row)
    if not colors:
        return out
    neutral = max(set(colors), key=colors.count)

    def fill_rect(r0, r1, c0, c1, color):
        for r in range(max(0, r0), min(h, r1)):
            for c in range(max(0, c0), min(w, c1)):
                if out[r][c] == 0:
                    out[r][c] = color

    # Connect non-neutral equal tile centers; retain the full size/shape of
    # their interior marker while filling only blank separator bands.
    for ri, (r0, r1) in enumerate(rb):
        for color in set(tiles[ri]):
            if color is None or color == neutral:
